"""Dedupe and month filtering (contract R5, R8; spec D11)."""


def dedupe(txs):
    """Return (kept, n_dupes); key is (date, description, amount), first wins."""
    seen = set()
    kept = []
    for tx in txs:
        key = (tx.date, tx.description, tx.amount)
        if key in seen:
            continue
        seen.add(key)
        kept.append(tx)
    return kept, len(txs) - len(kept)


def filter_month(txs, month):
    """Keep transactions whose date[:7] equals month; None keeps all."""
    if month is None:
        return list(txs)
    return [tx for tx in txs if tx.date[:7] == month]
